/* From Uiverse.io by Tsiangana  - Tags: twitter, instagram, modern, radio, creative */
.__UIV_SCOPE__ .radio-inputs {
  display: flex;
  justify-content: center;
  align-items: center;
  max-width: 350px;
  -webkit-user-select: none;
  -moz-user-select: none;
  -ms-user-select: none;
  user-select: none;
}

.__UIV_SCOPE__ .radio-inputs > * {
  margin: 6px;
}

.__UIV_SCOPE__ .instagram:checked + .radio-tile {
  border-color: #cc39a4;
  box-shadow: 0 5px 10px rgba(0, 0, 0, 0.1);
  color: #cc39a4;
}

.__UIV_SCOPE__ .instagram:checked + .radio-tile:before {
  transform: scale(1);
  opacity: 1;
  background-color: #cc39a4;
  border-color: #cc39a4;
}

.__UIV_SCOPE__ .instagram:checked + .radio-tile .radio-icon svg {
  fill: #fff;
}

.__UIV_SCOPE__ .instagram:checked + .radio-tile .radio-label {
  color: #cc39a4;
}

.__UIV_SCOPE__ .instagram:focus + .radio-tile {
  background-color: #cc39a4;
  border-color: #fff;
  box-shadow: 0 5px 10px rgba(0, 0, 0, 0.1), 0 0 0 4px #b5c9fc;
}
.__UIV_SCOPE__ .instagram:checked + .radio-tile {
  background-color: #cc39a4;
  border-color: #fff;
}

.__UIV_SCOPE__ .instagram:focus + .radio-tile:before {
  transform: scale(1);
  opacity: 1;
}

