.__UIV_SCOPE__ .radio-tile {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 80px;
  min-height: 80px;
  border-radius: 0.5rem;
  border: 2px solid #b5bfd9;
  background-color: #fff;
  box-shadow: 0 5px 10px rgba(0, 0, 0, 0.1);
  transition: 0.15s ease;
  cursor: pointer;
  position: relative;
}

.__UIV_SCOPE__ .instagram:hover {
  border-color: #cc39a4;
}
.__UIV_SCOPE__ .twitter:hover {
  border-color: #03a9f4;
}
.__UIV_SCOPE__ .discord:hover {
  border-color: #8c9eff;
}

.__UIV_SCOPE__ .radio-tile:hover:before {
  transform: scale(1);
  opacity: 1;
}

.__UIV_SCOPE__ .radio-icon svg {
  width: 2rem;
  height: 2rem;
}
.__UIV_SCOPE__ .instagram {
  fill: #cc39a4;
}
.__UIV_SCOPE__ .twitter {
  fill: #03a9f4;
}
.__UIV_SCOPE__ .discord {
  fill: #8c9eff;
}

.__UIV_SCOPE__ .radio-label {
  color: #707070;
  transition: 0.375s ease;
  text-align: center;
  font-size: 13px;
}

.__UIV_SCOPE__ .radio-input {
  clip: rect(0 0 0 0);
  -webkit-clip-path: inset(100%);
  clip-path: inset(100%);
  height: 1px;
  overflow: hidden;
  position: absolute;
  white-space: nowrap;
  width: 1px;
}
